  const parts = [];
  if (row.min !== undefined && row.max !== undefined) parts.push(`${row.min} – ${row.max}`);
  else if (row.min !== undefined) parts.push(`at least ${row.min}`);
  else if (row.max !== undefined) parts.push(`at most ${row.max}`);
